543	func defaultCloneHomeJurisdiction(ctx context.Context) string {
544		// Match coreapi's presence-based env-token precedence: when ENTIRE_TOKEN is
545		// set it is the bearer the placement lookup actually used, so derive the
546		// home jurisdiction from it, not from the stored active context.
547		if raw, ok := os.LookupEnv(auth.EnvTokenVar); ok {
548			_, token, err := auth.ParseEnvToken(raw)
549			if err != nil {
550				return ""
551			}
552			jur, err := auth.HomeJurisdictionFromLoginJWT(token)
553			if err != nil {
554				return ""
555			}
556			return strings.TrimSpace(jur)
557		}
558	
559		target, err := auth.ResolveControlPlaneTarget()
560		if err != nil {
561			return ""
562		}
563		jwt, err := target.TokenSource(ctx)
564		if err != nil {
565			return ""
566		}
567		jur, err := auth.HomeJurisdictionFromLoginJWT(jwt)
568		if err != nil {
569			return ""
570		}
571		return strings.TrimSpace(jur)
572	}
573	
574	// preferHomeJurisdiction narrows placements to those in the caller's home
575	// jurisdiction, so the picker isn't cluttered with regions the user doesn't
576	// belong to (and auto-selects when that leaves exactly one). Best-effort: an
577	// unknown home, or a home that matches no placement, returns the input
578	// unchanged so a clonable target is never silently hidden.
579	func preferHomeJurisdiction(placements []coreapi.ResolvedPlacement, home string) []coreapi.ResolvedPlacement {
580		if home == "" || len(placements) < 2 {
581			return placements
582		}
583		kept := make([]coreapi.ResolvedPlacement, 0, len(placements))
584		for _, p := range placements {
585			if strings.EqualFold(strings.TrimSpace(p.Jurisdiction.Or("")), home) {
586				kept = append(kept, p)
587			}
588		}
589		if len(kept) == 0 {
590			return placements
591		}
592		return kept
593	}
594	
595	// selectCloneTarget resolves which mirror placement to clone from, with the
596	// clone verb's wording. See selectPlacement for the selection rules. With no
597	// explicit --cluster it first narrows to the caller's home jurisdiction so a
598	// repo mirrored across many regions defaults to the user's own.
599	func selectCloneTarget(cmd *cobra.Command, placements []coreapi.ResolvedPlacement, clusterFlag string) (coreapi.ResolvedPlacement, error) {
600		if clusterFlag == "" {
